ALTER TABLE public.plan_reports DROP CONSTRAINT plan_reports_report_key_check;
ALTER TABLE public.plan_reports ADD CONSTRAINT plan_reports_report_key_check CHECK (report_key IN ('fs5','fs3','fs1','verification','shareholders','pnl','risk','credit'));
INSERT INTO public.plan_reports(plan_id,report_key,mode,per_term) SELECT id,'shareholders','none',NULL FROM public.plans WHERE role='buyer' ON CONFLICT DO NOTHING;
ALTER TABLE public.report_orders DROP CONSTRAINT report_orders_kind_check;
ALTER TABLE public.report_orders ADD CONSTRAINT report_orders_kind_check CHECK(kind IN ('financials','valuation','bundle','risk','shareholders','pnl','credit'));
ALTER TABLE public.report_shares ADD COLUMN report_keys text[] NOT NULL DEFAULT '{}';
ALTER TABLE public.report_shares ADD COLUMN report_opened_at jsonb NOT NULL DEFAULT '{}';
UPDATE public.report_shares SET report_keys=CASE WHEN financials THEN ARRAY['statements','pnl']::text[] ELSE '{}'::text[] END;
CREATE TABLE public.company_report_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.startups(id),report_key text NOT NULL CHECK(report_key IN ('verification','shareholders','statements','pnl','risk','credit')),status text NOT NULL DEFAULT 'not_ordered' CHECK(status IN ('not_ordered','in_progress','generated','ready')),generated_at timestamptz,authorised_at timestamptz,authorised_by uuid,ready_by timestamptz,content jsonb,source_filed_on date,checked_on date,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,report_key));
GRANT ALL ON public.company_report_records TO service_role;
ALTER TABLE public.company_report_records ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.buyer_report_access(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.startups(id),buyer_id uuid NOT NULL,pipeline_id uuid NOT NULL REFERENCES public.deal_pipelines(id),report_key text NOT NULL CHECK(report_key IN ('verification','shareholders','statements','pnl','risk','credit')),via text NOT NULL CHECK(via IN ('plan','paid','contract')),opened_at timestamptz NOT NULL DEFAULT now(),last_opened_at timestamptz,order_id uuid REFERENCES public.report_orders(id),UNIQUE(company_id,buyer_id,report_key));
GRANT ALL ON public.buyer_report_access TO service_role;
ALTER TABLE public.buyer_report_access ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.report_share_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.startups(id),pipeline_id uuid NOT NULL REFERENCES public.deal_pipelines(id),buyer_id uuid NOT NULL,report_key text NOT NULL CHECK(report_key IN ('verification','shareholders','statements','pnl','risk','credit')),status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','shared','declined')),requested_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,resolved_by uuid);
GRANT ALL ON public.report_share_requests TO service_role;
ALTER TABLE public.report_share_requests ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX report_request_one_open ON public.report_share_requests(company_id,buyer_id,report_key) WHERE status='open';
CREATE TABLE public.report_open_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.startups(id),pipeline_id uuid NOT NULL REFERENCES public.deal_pipelines(id),buyer_id uuid NOT NULL,report_key text NOT NULL,via text NOT NULL,opened_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.report_open_events TO service_role;
ALTER TABLE public.report_open_events ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.reports_pipeline_nda(_pipeline uuid,_buyer uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.deal_pipelines p WHERE p.id=_pipeline AND p.buyer_user_id=_buyer AND p.nda_approved_at IS NOT NULL AND p.status NOT IN ('declined','withdrawn','revoked','ended') AND coalesce(p.nda_expires_at,p.nda_approved_at+interval '730 days')>now()); $$;
REVOKE ALL ON FUNCTION public.reports_pipeline_nda(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reports_pipeline_nda(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.reports_open_plan(_buyer uuid,_pipeline uuid,_report text,_plan_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.deal_pipelines; s public.subscriptions; r public.plan_reports; used integer; a public.buyer_report_access; BEGIN IF NOT public.reports_pipeline_nda(_pipeline,_buyer) THEN RAISE EXCEPTION 'An approved active NDA is required'; END IF; SELECT * INTO d FROM public.deal_pipelines WHERE id=_pipeline FOR UPDATE; IF _report NOT IN ('verification','shareholders','statements','pnl','risk','credit') OR (_report='statements' AND _plan_key NOT IN ('fs5','fs3','fs1')) OR (_report<>'statements' AND _plan_key<>_report) THEN RAISE EXCEPTION 'Invalid report'; END IF; SELECT * INTO a FROM public.buyer_report_access WHERE company_id=d.startup_id AND buyer_id=_buyer AND report_key=_report; IF FOUND THEN RETURN jsonb_build_object('reopened',true); END IF; SELECT * INTO s FROM public.subscriptions WHERE user_id=_buyer FOR UPDATE; IF NOT FOUND OR s.status='ended' OR (s.term_end IS NOT NULL AND s.term_end<=now()) THEN RAISE EXCEPTION 'Choose an active plan'; END IF; SELECT pr.* INTO r FROM public.plan_reports pr JOIN public.plans p ON p.id=pr.plan_id WHERE pr.plan_id=s.plan_id AND p.role='buyer' AND p.status='live' AND pr.report_key=_plan_key; IF NOT FOUND OR r.mode='none' THEN RAISE EXCEPTION 'This report is not included in your plan'; END IF; IF r.mode='number' THEN SELECT count(*) INTO used FROM public.plan_usage WHERE user_id=_buyer AND kind='report:'||_plan_key AND term_start=s.term_start; IF used>=coalesce(r.per_term,0) THEN RAISE EXCEPTION 'No reports left in your plan'; END IF; END IF; INSERT INTO public.plan_usage(user_id,kind,ref,term_start) SELECT _buyer,'report:'||_plan_key,d.startup_id::text,s.term_start WHERE NOT EXISTS(SELECT 1 FROM public.plan_usage WHERE user_id=_buyer AND kind='report:'||_plan_key AND ref=d.startup_id::text AND term_start=s.term_start); INSERT INTO public.buyer_report_access(company_id,buyer_id,pipeline_id,report_key,via) VALUES(d.startup_id,_buyer,_pipeline,_report,CASE WHEN r.mode='contract' THEN 'contract' ELSE 'plan' END); INSERT INTO public.company_report_records(company_id,report_key,status,ready_by) VALUES(d.startup_id,_report,'in_progress',public.verification_business_due(now(),1)) ON CONFLICT(company_id,report_key) DO NOTHING; RETURN jsonb_build_object('reopened',false); END; $$;
REVOKE ALL ON FUNCTION public.reports_open_plan(uuid,uuid,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reports_open_plan(uuid,uuid,text,text) TO service_role;
COMMENT ON TABLE public.company_report_records IS 'Six-report hub: private analyst records; no fabricated findings. Existing financial/verification records remain canonical.';
COMMENT ON TABLE public.buyer_report_access IS 'Durable bought/plan entitlements. Pipeline UI still requires a selected active NDA; shares revoke separately.';
COMMENT ON COLUMN public.report_shares.report_keys IS 'Independent six-report grants supplement legacy financials/valuation flags.';